changeSet.sql:
DO $$ DECLARE target_check record;
BEGIN
  FOR target_check IN SELECT conname FROM pg_constraint
    WHERE conrelid = 'chats'::regclass AND contype = 'c'
      AND pg_get_constraintdef(oid) LIKE '%cible%'
  LOOP
    EXECUTE format('ALTER TABLE chats DROP CONSTRAINT %I', target_check.conname);
  END LOOP;
END $$;
